package EmployeeManagementSystem.service;
import EmployeeManagementSystem.entity.*; import EmployeeManagementSystem.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*; import java.util.*;
@Service @Transactional public class EmployeeSurveyServiceImpl implements EmployeeSurveyService{
 private final EmployeeSurveyRepository surveys; private final EmployeeSurveyResponseRepository responses;
 public EmployeeSurveyServiceImpl(EmployeeSurveyRepository s,EmployeeSurveyResponseRepository r){surveys=s;responses=r;}
 public List<EmployeeSurvey> all(){return surveys.findAllByOrderByCreatedAtDesc();}
 public List<EmployeeSurvey> active(){LocalDateTime n=LocalDateTime.now();return surveys.findAllByOrderByCreatedAtDesc().stream().filter(s->"PUBLISHED".equals(s.getStatus())&&(s.getStartAt()==null||!n.isBefore(s.getStartAt()))&&(s.getEndAt()==null||!n.isAfter(s.getEndAt()))).toList();}
 public EmployeeSurvey create(EmployeeSurvey s){s.setId(null);s.setStatus("DRAFT");s.setSurveyNumber("SUR-"+String.format("%06d",System.currentTimeMillis()%1000000));return surveys.save(s);}
 public EmployeeSurvey update(Long id,EmployeeSurvey in){EmployeeSurvey s=surveys.findById(id).orElseThrow(()->new IllegalArgumentException("Survey not found"));if("PUBLISHED".equals(s.getStatus()))throw new IllegalArgumentException("Published survey cannot be edited");s.setTitle(in.getTitle());s.setDescription(in.getDescription());s.setQuestion(in.getQuestion());s.setCategory(in.getCategory());s.setAnonymous(in.getAnonymous());s.setStartAt(in.getStartAt());s.setEndAt(in.getEndAt());return surveys.save(s);}
 public EmployeeSurvey publish(Long id){EmployeeSurvey s=surveys.findById(id).orElseThrow(()->new IllegalArgumentException("Survey not found"));s.setStatus("PUBLISHED");if(s.getStartAt()==null)s.setStartAt(LocalDateTime.now());return surveys.save(s);}
 public EmployeeSurvey close(Long id){EmployeeSurvey s=surveys.findById(id).orElseThrow(()->new IllegalArgumentException("Survey not found"));s.setStatus("CLOSED");if(s.getEndAt()==null)s.setEndAt(LocalDateTime.now());return surveys.save(s);}
 public EmployeeSurveyResponse respond(Long id,String userId,String name,Integer rating,String comment){EmployeeSurvey s=surveys.findById(id).orElseThrow(()->new IllegalArgumentException("Survey not found"));if(!"PUBLISHED".equals(s.getStatus()))throw new IllegalArgumentException("Survey is not open");if(responses.findBySurvey_IdAndUserId(id,userId).isPresent())throw new IllegalArgumentException("You have already responded to this survey");if(rating==null||rating<1||rating>5)throw new IllegalArgumentException("Rating must be between 1 and 5");EmployeeSurveyResponse r=new EmployeeSurveyResponse();r.setSurvey(s);r.setUserId(userId);r.setEmployeeName(Boolean.TRUE.equals(s.getAnonymous())?"Anonymous":name);r.setRating(rating);r.setComment(comment);return responses.save(r);}
 public List<EmployeeSurveyResponse> responses(Long id){return responses.findBySurvey_Id(id);}
 public Optional<EmployeeSurveyResponse> myResponse(Long id,String userId){return responses.findBySurvey_IdAndUserId(id,userId);}
}
